CREATE OR REPLACE FUNCTION shipment_outbox() RETURNS trigger AS $$ DECLARE eid uuid:=gen_random_uuid();et text;rk text;BEGIN et:=CASE WHEN TG_OP='INSERT' THEN 'ShipmentCreated' WHEN NEW.status='SHIPPING' THEN 'ShipmentShippingStarted' WHEN NEW.status='DELIVERED' THEN 'ShipmentDelivered' WHEN NEW.status='CANCELLED' THEN 'ShipmentFailed' ELSE 'ShipmentStatusChanged' END;rk:=CASE et WHEN 'ShipmentCreated' THEN 'shipment.created' WHEN 'ShipmentShippingStarted' THEN 'shipment.shipping' WHEN 'ShipmentDelivered' THEN 'shipment.delivered' WHEN 'ShipmentFailed' THEN 'shipment.failed' ELSE 'shipment.status' END;INSERT INTO outbox_events(id,aggregate_type,aggregate_id,event_type,event_version,payload,status,created_at)VALUES(eid,'Shipment',NEW.id::text,et,1,jsonb_build_object('eventId',eid,'eventType',et,'eventVersion',1,'aggregateType','Shipment','aggregateId',NEW.id::text,'occurredAt',now(),'traceId',gen_random_uuid(),'producer','logistics-service','routingKey',rk,'payload',jsonb_build_object('shipmentId',NEW.id,'orderId',NEW.order_id,'status',NEW.status)),'PENDING',now());RETURN NEW;END$$ LANGUAGE plpgsql;
CREATE TRIGGER trg_shipment_outbox AFTER INSERT OR UPDATE OF status ON shipments FOR EACH ROW EXECUTE FUNCTION shipment_outbox();
